          "requestedSpend": "1000.00",
          "sanctionsStatus": "UNKNOWN",
          "countryRisk": "LOW"
        }
      },
      "evidenceAvailability": {
        "financial-evidence": "present"
      },
      "expectedDisposition": {
        "kind": "unresolved",
        "reasons": ["no-match"],
        "handoff": {
          "state": "requested",
          "triggeredBy": ["no-match"]
        }
      },
      "expectedHandoffTarget": {
        "kind": "queue",
        "name": "vendor-compliance-desk"
      }
    },
    {
      "id": "o3-precedes-critical-and-rejection",
      "facts": {
        "vendor": {
